from collections import deque
def comps(g,val,bg):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==val and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); c=[]
                while q:
                    y,x=q.popleft(); c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ay,ax=y+dy,x+dx
                        if 0<=ay<h and 0<=ax<w and g[ay][ax]==val and (ay,ax) not in seen:
                            seen.add((ay,ax)); q.append((ay,ax))
                out.append(c)
    return out
